import json

# Helper to safely parse CLI JSON output (strip trailing shell prompt)
def parse_cli_json(raw):
    # Find the JSON object boundaries
    start = raw.find('{')
    if start == -1:
        return {"error": "No JSON found", "raw": raw}
    depth = 0
    end = start
    for i in range(start, len(raw)):
        if raw[i] == '{':
            depth += 1
        elif raw[i] == '}':
            depth -= 1
            if depth == 0:
                end = i + 1
                break
    return json.loads(raw[start:end])

